/* @lc app=leetcode id=2019 lang=kotlin */
class Solution { fun scoreOfStudents(s: String, answers: IntArray) = (s.split('+').sumOf { it.split('*').map(String::toInt).reduce { a, b -> a * b } }).let { correct -> Array(s.length + 1) { Array(s.length + 1) { mutableSetOf<Int>() } }.apply { (0 until s.length step 2).forEach { i -> this[i][i + 1].add(s[i] - '0') } }.apply { (3..s.length step 2).forEach { len -> (0..s.length - len step 2).forEach { i -> (1 until len step 2).forEach { k -> this[i][i + k].forEach { left -> this[i + k + 1][i + len].forEach { right -> if (s[i + k] == '+' && left + right <= 1000) this[i][i + len].add(left + right) else if (s[i + k] == '*' && left * right <= 1000) this[i][i + len].add(left * right) } } } } } }.let { dp -> answers.sumOf { if (it == correct) 5 else if (dp[0][s.length].contains(it)) 2 else 0 } } } }